generation_rounds.planner_raw:
{
  "strategy": "Localize the specific chart/graphic that shows global manufacturing share over time, then retrieve a small set of frames from that interval and use chart analysis to read the crossover year directly. This is the minimal evidence chain for a chart-based multiple-choice question.",
  "tool_calls": [
    {
      "step": 1,
      "tool": "temporal_grounder",
      "arguments": {
        "video_path": "VIDEO",
        "query": "chart or animated graphic showing global manufacturing share over time for China and the United States"
      },
      "purpose": "Find the time window where the answer-critical statistics graphic appears, instead of searching the whole video blindly.",
      "depends_on": []
    },
    {
      "step": 2,
      "tool": "frame_retriever",
      "arguments": {
        "video_path": "VIDEO",
        "query": null,
        "timestamps": [
          "<STEP_1:segments[0].start>",
          "<STEP_1:segments[0].end>",
          "<STEP_1:segments[1].start>"
        ],
        "num_frames": 3
      },
      "purpose": "Sample likely candidate frames from top localized chart intervals so the downstream chart reader can inspect alternate chart states rather than assuming one interval/frame is sufficient.",
      "depends_on": [
        1
      ]
    },
    {
      "step": 3,
      "tool": "chart_analyzer",
      "arguments": {
        "frame_path": "<STEP_2:frames>",
        "timestamp": null,
        "query": "line or chart showing China and U.S. global manufacturing share; identify the year when China's share overtakes the U.S. share"
      },
      "purpose": "Read the chart structure and determine the crossover year that directly answers the multiple-choice question.",
      "depends_on": [
        2
      ]
    }
  ],
  "refinement_instructions": "Write a first-principles trace from scratch. Use step 1 only to justify the relevant chart interval; do not treat the top-ranked segment as automatically earliest or uniquely correct beyond locating the manufacturing-share graphic. In step 2, inspect the returned frame timestamps and keep the frame-level evidence separate if they show different chart states. In step 3, use the frame-level chart analysis result that explicitly identifies both series (China and U.S.) and the crossover year. Cite chart_analyzer as the authority for the overtake year. If the returned year is approximate or between labeled ticks, explain the closest-option mapping explicitly before selecting the answer choice. If different sampled frames show complementary but compatible chart evidence, combine them only by the stable series labels China and U.S.; do not assume all evidence must come from one frame. Update the final answer to the option matching the verified overtake year."
}
